export const H264_AAC_MP4_BASE64 = '';

export const VP9_WEBM_BASE64 = '';

export function decodeBase64(value: string): Uint8Array {
  const raw = atob(value);
  return Uint8Array.from(raw, (character) => character.charCodeAt(0));
}

export function makePcm16Wav(durationSeconds = 0.6, sampleRate = 24_000): Uint8Array {
  const frameCount = Math.round(durationSeconds * sampleRate);
  const dataBytes = frameCount * 2;
  const bytes = new Uint8Array(44 + dataBytes);
  const view = new DataView(bytes.buffer);
  const text = (offset: number, value: string) => {
    for (let index = 0; index < value.length; index += 1) bytes[offset + index] = value.charCodeAt(index);
  };
  text(0, 'RIFF');
  view.setUint32(4, 36 + dataBytes, true);
  text(8, 'WAVE');
  text(12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * 2, true);
  view.setUint16(32, 2, true);
  view.setUint16(34, 16, true);
  text(36, 'data');
  view.setUint32(40, dataBytes, true);
  for (let frame = 0; frame < frameCount; frame += 1) {
    const sample = Math.sin(2 * Math.PI * 880 * frame / sampleRate) * 0.25;
    view.setInt16(44 + frame * 2, Math.max(-32768, Math.min(32767, Math.round(sample * 32767))), true);
  }
  return bytes;
}
